impl KernelId {
	pub(crate) const fn mldsa_keygen_layout(parameter: u32) -> Option<(u64, u64, u64)> {
		match parameter {
			44 => Some((32, 1312, 2560)),
			65 => Some((32, 1952, 4032)),
			87 => Some((32, 2592, 4896)),
			_ => None,
		}
	}
	pub(crate) const fn mldsa_sign_layout(parameter: u32) -> Option<(u64, u64, u64, u64)> {
		match parameter {
			44 => Some((32, 2560, 64, 2420)),
			65 => Some((32, 4032, 64, 3309)),
			87 => Some((32, 4896, 64, 4627)),
			_ => None,
		}
	}
	pub(crate) const fn mldsa_sign_workspace_bytes() -> usize {
		23552
	}
	pub(crate) const fn mldsa_prehash_bytes(algorithm: u32) -> Option<u64> {
		match algorithm {
			1 => Some(32),
			2 => Some(48),
			3 => Some(64),
			4 => Some(28),
			5 => Some(28),
			6 => Some(32),
			7 => Some(28),
			8 => Some(32),
			9 => Some(48),
			10 => Some(64),
			11 => Some(32),
			12 => Some(64),
			_ => None,
		}
	}

	/// FIPS 204 M' head words for the public mu kernel: the 0x00 or 0x01
	/// domain tag, the context length byte and, for HashML-DSA, the
	/// eleven-byte OID trailer, packed little-endian. Returns the four
	/// push words and the live byte count (2 or 13).
	pub(crate) const fn mldsa_mu_head(
		algorithm: u32,
		context_length: u32,
	) -> Option<([u32; 4], u32)> {
		if context_length > 255 {
			return None;
		}
		if algorithm == 0 {
			return Some(([context_length << 8, 0, 0, 0], 2));
		}
		if Self::mldsa_prehash_bytes(algorithm).is_none() {
			return None;
		}
		Some((
			[
				0x0906_0001 | context_length << 8,
				0x0148_8660,
				0x0204_0365,
				algorithm,
			],
			13,
		))
	}
}

