	pub(crate) const fn requires_secret_storage(self) -> bool {
		matches!(
			self,
			Self::CryptographyMlKemKeygenU8
				| Self::CryptographyMlKemEncapsU8
				| Self::CryptographyMlKemDecapsU8
				| Self::CryptographyMlDsaKeygenU8
				| Self::CryptographyMlDsaSignU8
				| Self::CryptographyMlKemSharedDeriveU8
		)
	}

